package au.edu.uow.csci318.assessment.controller;
import au.edu.uow.csci318.assessment.application.AssessmentApplicationService;import au.edu.uow.csci318.assessment.dto.AssessmentDtos.*;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/assessments") @CrossOrigin public class AssessmentController{private final AssessmentApplicationService service;private final au.edu.uow.csci318.assessment.infrastructure.IdentityClient identity;public AssessmentController(AssessmentApplicationService s,au.edu.uow.csci318.assessment.infrastructure.IdentityClient identity){service=s;this.identity=identity;}
 @PostMapping("/import")@ResponseStatus(HttpStatus.CREATED)public List<Response>importAll(@RequestHeader("Authorization")String auth,@Valid@RequestBody ImportRequest r){return service.importAll(identity.require(auth),auth,r);}@PostMapping@ResponseStatus(HttpStatus.CREATED)public Response create(@RequestHeader("Authorization")String auth,@Valid@RequestBody CreateRequest r){return service.create(identity.require(auth),auth,r);}@GetMapping public List<Response>all(@RequestHeader("Authorization")String auth,@RequestParam(required=false)String status,@RequestParam(required=false)UUID subjectId){return service.all(identity.require(auth),status,subjectId);}@GetMapping("/{id}")public Response one(@RequestHeader("Authorization")String auth,@PathVariable UUID id){return service.one(identity.require(auth),id);}@PatchMapping("/{id}")public Response update(@RequestHeader("Authorization")String auth,@PathVariable UUID id,@RequestBody UpdateRequest r){return service.update(identity.require(auth),id,r);}@PostMapping("/{id}/complete")public Response complete(@RequestHeader("Authorization")String auth,@PathVariable UUID id){return service.complete(identity.require(auth),id);}@DeleteMapping("/{id}")@ResponseStatus(HttpStatus.NO_CONTENT)public void delete(@RequestHeader("Authorization")String auth,@PathVariable UUID id){service.delete(identity.require(auth),id);}}
